SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, CASE WHEN amount >= 1580 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, DATE_TRUNC('QUARTER', order_date) AS quarter_start, PERCENTILE_APPROX(amount, 0.95) AS amount_p95, COUNT(CASE WHEN status = 'PENDING' THEN 1 END) AS pending_count, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows FROM orders GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', order_date), CASE WHEN amount >= 1580 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('QUARTER', order_date)), (DATE_TRUNC('MONTH', order_date), CASE WHEN amount >= 1580 THEN 'PREMIUM' ELSE 'STANDARD' END)) ORDER BY amount_p95 DESC;
